package br.com.bancohorizonte.http; import com.fasterxml.jackson.databind.*; import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule; import java.io.*; import java.nio.charset.StandardCharsets;
public final class Json { public static final ObjectMapper MAPPER=new ObjectMapper().registerModule(new JavaTimeModule()); private Json(){} public static <T>T ler(InputStream in,Class<T> tipo)throws IOException{return MAPPER.readValue(in,tipo);} public static void responder(com.sun.net.httpserver.HttpExchange ex,int status,Object body)throws IOException{byte[] bytes=MAPPER.writeValueAsBytes(body);ex.getResponseHeaders().set("Content-Type","application/json; charset=utf-8");ex.sendResponseHeaders(status,bytes.length);try(OutputStream out=ex.getResponseBody()){out.write(bytes);}} }
